/* widgets/cs-trace.js (GENERATED by data/cs.trace_gen.py from data/cs-trace.tpl.js: edit the template, not this file).
   <div class="widget" data-w="cs-trace" data-prog="total"></div>
   data-prog: total | grade | validate | countdown | vowels. The widget steps through a built-in pseudocode program one
   line at a time and grows a trace table as Cambridge draws it. It never interprets pseudocode: every step was
   produced by data/cs.trace_gen.py, which runs a Python translation of each program. */
(function () {
  'use strict';

  const PROGRAMS = /*PROGRAMS*/null;
  const NAMES = Object.keys(PROGRAMS);

  // ---- pure helpers (also tested in Node: data/cs-trace.test.js) ----
  // The trace-table rows after the first k events: a row for every event that changes a value or prints something.
  function rowsUpTo(run, k) {
    const rows = [];
    for (let i = 0; i < k && i < run.events.length; i++) {
      const ev = run.events[i];
      const keys = Object.keys(ev.set);
      if (keys.length === 0 && ev.out === undefined) continue;
      const cells = {};
      keys.forEach(function (key) { cells[key] = ev.set[key]; });
      if (ev.out !== undefined) cells.OUTPUT = ev.out;
      rows.push({ line: ev.line, cells: cells, step: i + 1 });
    }
    return rows;
  }

  function currentLine(run, k) {
    return k > 0 && k <= run.events.length ? run.events[k - 1].line : 0;
  }

  if (typeof module !== 'undefined' && module.exports) {
    module.exports = { PROGRAMS: PROGRAMS, rowsUpTo: rowsUpTo, currentLine: currentLine };
  }
  if (typeof W === 'undefined' || !W.register) return;

  // ---- the widget ----
  W.register('cs-trace', function (el, opts) {
    const f = W.frame(el, 'Trace a program line by line', 'Press Next to run one line at a time and watch the trace table grow');
    const body = f.body;
    const mono = 'ui-monospace, SFMono-Regular, Menlo, Consolas, monospace';

    let name = String((opts && opts.prog) || 'total').trim();
    if (!PROGRAMS[name]) {
      const err = W.h('div', { class: 'w-err', text: 'Unknown program "' + name + '". The programs are: ' + NAMES.join(', ') + '.' });
      err.setAttribute('role', 'alert');
      body.appendChild(err);
      return;
    }
    const prog = PROGRAMS[name];
    let run = prog.runs[0];
    let stepper = null;

    body.appendChild(W.h('p', { class: 'w-note', style: { fontWeight: '600', margin: '0 0 6px' }, text: prog.title }));

    // choose which typed values to run with (only when the program has more than one run)
    let select = null;
    if (prog.runs.length > 1) {
      select = W.h('select', {});
      prog.runs.forEach(function (r, i) { select.appendChild(W.h('option', { value: String(i), text: r.label })); });
      select.setAttribute('aria-label', 'Typed values for the run');
      select.addEventListener('change', function () {
        run = prog.runs[Number(select.value)] || prog.runs[0];
        build();
        stepper.go(0);
      });
      body.appendChild(W.h('div', { class: 'w-row' }, W.h('label', { class: 'w-ctl' }, W.h('span', { class: 'w-lab', text: 'Typed values for this run' }), select)));
    }

    const typed = W.h('p', { class: 'w-note', style: { margin: '4px 0' } });
    body.appendChild(typed);

    const listing = W.h('div', { style: { fontFamily: mono, fontSize: '14px', lineHeight: '1.6', overflowX: 'auto', border: '1px solid var(--rule)', borderRadius: '6px', padding: '6px 8px', background: 'var(--card)', margin: '6px 0' } });
    listing.setAttribute('role', 'group');
    listing.setAttribute('aria-label', 'Pseudocode program, the line being run is marked with an arrow');
    body.appendChild(listing);

    const live = W.h('p', { style: { margin: '4px 0', minHeight: '2.8em' } });
    live.setAttribute('aria-live', 'polite');
    body.appendChild(live);

    const tableWrap = W.h('div', { style: { overflowX: 'auto' } });
    body.appendChild(tableWrap);

    const resetBtn = W.h('button', { class: 'btn btn-sm btn-sec', type: 'button', text: 'Reset' });
    resetBtn.setAttribute('aria-label', 'Reset to the start of the program');

    let lineEls = [];
    function build() {
      typed.textContent = run.inputs.length ? 'Typed values, in order: ' + run.inputs.join(', ') + '.' : 'This program asks for no input.';
      listing.textContent = '';
      lineEls = [];
      prog.lines.forEach(function (text, i) {
        const mark = W.h('span', { text: ' ', style: { display: 'inline-block', width: '1.5em', color: 'var(--sc)', fontWeight: '700' } });
        mark.setAttribute('aria-hidden', 'true');
        const num = W.h('span', { text: String(i + 1).padStart(2, ' ') + ' ', style: { color: 'var(--ink-3)', whiteSpace: 'pre' } });
        mark.style.flexShrink = '0';
        num.style.flexShrink = '0';
        const code = W.h('span', { text: text, style: { whiteSpace: 'pre-wrap', overflowWrap: 'anywhere', minWidth: '0' } });
        const row = W.h('div', { style: { display: 'flex', borderRadius: '3px', padding: '0 2px' } }, mark, num, code);
        listing.appendChild(row);
        lineEls.push({ row: row, mark: mark });
      });
    }

    function th(text) { return W.h('th', { text: text, scope: 'col', style: { textAlign: 'left', whiteSpace: 'nowrap', padding: '4px 8px' } }); }

    function show(k) {
      const cur = currentLine(run, k);
      lineEls.forEach(function (l, i) {
        const on = i + 1 === cur;
        l.mark.textContent = on ? '▶' : ' ';
        l.row.style.background = on ? 'var(--hl-soft)' : 'transparent';
        l.row.style.fontWeight = on ? '700' : '400';
      });
      if (k === 0) live.textContent = 'Nothing has run yet. Press Next to run line 1.';
      else {
        const ev = run.events[k - 1];
        live.textContent = 'Line ' + ev.line + ': ' + ev.note + (k === run.events.length ? ' The program has finished.' : '');
      }
      const rows = rowsUpTo(run, k);
      const cols = prog.columns;
      const table = W.h('table', { style: { borderCollapse: 'collapse', fontFamily: mono, fontSize: '14px', width: 'auto' } });
      table.setAttribute('aria-label', 'Trace table');
      const head = W.h('tr', {}, th('Line'));
      cols.forEach(function (c) { head.appendChild(th(c)); });
      table.appendChild(W.h('thead', {}, head));
      const tb = W.h('tbody', {});
      rows.forEach(function (r, i) {
        const tr = W.h('tr', {}, W.h('td', { text: String(r.line), style: { padding: '3px 8px', color: 'var(--ink-3)' } }));
        const last = i === rows.length - 1;
        cols.forEach(function (c) {
          const v = r.cells[c];
          tr.appendChild(W.h('td', { text: v === undefined ? '' : v, style: { padding: '3px 8px', fontWeight: last ? '700' : '400', whiteSpace: 'nowrap' } }));
        });
        tb.appendChild(tr);
      });
      if (rows.length === 0) {
        const tr = W.h('tr', {}, W.h('td', { text: '(no rows yet)', colspan: String(cols.length + 1), style: { padding: '3px 8px', color: 'var(--ink-3)' } }));
        tb.appendChild(tr);
      }
      table.appendChild(tb);
      tableWrap.textContent = '';
      tableWrap.appendChild(table);
    }

    // own Back / Next (runs differ in length, so W.stepper's fixed step count does not fit)
    let k = 0;
    const back = W.h('button', { class: 'btn btn-sm btn-sec', type: 'button', text: 'Back' });
    const next = W.h('button', { class: 'btn btn-sm', type: 'button', text: 'Next' });
    const lab = W.h('span', { class: 'w-step' });
    const bar = W.h('div', { class: 'w-row w-stepper' }, back, lab, next, resetBtn);
    function go(n) {
      k = Math.max(0, Math.min(run.events.length, n));
      back.disabled = k === 0;
      next.disabled = k === run.events.length;
      lab.textContent = k === 0 ? 'Start' : 'Step ' + k + ' of ' + run.events.length;
      show(k);
      const a = document.activeElement;
      if (a && a.disabled && bar.contains(a)) resetBtn.focus();
    }
    back.addEventListener('click', function () { go(k - 1); });
    next.addEventListener('click', function () { go(k + 1); });
    resetBtn.addEventListener('click', function () { go(0); });
    f.root.setAttribute('tabindex', f.root.getAttribute('tabindex') || '-1');
    f.root.addEventListener('keydown', function (e) {
      if (/input|select|textarea/i.test(e.target.tagName)) return;
      if (e.key === 'ArrowRight') { e.preventDefault(); go(k + 1); }
      else if (e.key === 'ArrowLeft') { e.preventDefault(); go(k - 1); }
    });
    stepper = { go: go };
    body.appendChild(bar);
    build();
    body.appendChild(W.h('p', { class: 'w-note', text: 'A new row is added whenever a value changes or something is output; blank cells mean "unchanged". The arrow ▶ marks the line that has just run. This tool shows steps worked out in advance; it does not read your own pseudocode.' }));
    go(0);
  });
})();
